import{_ as t,o as a,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"如何面对焦虑","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-焦虑.md","filePath":"20-专题研究/topic-焦虑.md","lastUpdated":1778155802000}'),i={name:"20-专题研究/topic-焦虑.md"};function l(h,o,u,s,d,n){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="如何面对焦虑" tabindex="-1">如何面对焦虑 <a class="header-anchor" href="#如何面对焦虑" aria-label="Permalink to &quot;如何面对焦虑&quot;">​</a></h1><blockquote><p>专题分析：焦虑的根源与化解之道 组合模型：对境不住 + 自然务实 + 对法不执</p></blockquote><hr><h2 id="一、焦虑的本质" tabindex="-1">一、焦虑的本质 <a class="header-anchor" href="#一、焦虑的本质" aria-label="Permalink to &quot;一、焦虑的本质&quot;">​</a></h2><p>焦虑源于<strong>对未来的不确定性的执着</strong>。</p><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。过去已成过去，未来还没有来，现在却不断地在流动。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><ul><li><strong>对境不住</strong>：焦虑是对&quot;未来情境&quot;的提前反应——事情还没发生，心已经被想象中的&quot;相&quot;带跑了</li><li><strong>自然务实</strong>：焦虑源于&quot;想得太多，做得太少&quot;</li><li><strong>对法不执</strong>：焦虑源于对结果的执着——非要某个结果才安心</li></ul><hr><h2 id="二、三种常见焦虑与对治" tabindex="-1">二、三种常见焦虑与对治 <a class="header-anchor" href="#二、三种常见焦虑与对治" aria-label="Permalink to &quot;二、三种常见焦虑与对治&quot;">​</a></h2><h3 id="_1-对未来恐惧型焦虑" tabindex="-1">1. 对未来恐惧型焦虑 <a class="header-anchor" href="#_1-对未来恐惧型焦虑" aria-label="Permalink to &quot;1. 对未来恐惧型焦虑&quot;">​</a></h3><p>担心事情失败、健康出问题、失去。</p><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><p>未来还没有来，你在焦虑一个不存在的东西。该做的准备去做，不该担心的不要提前透支情绪。</p><h3 id="_2-对选择的焦虑" tabindex="-1">2. 对选择的焦虑 <a class="header-anchor" href="#_2-对选择的焦虑" aria-label="Permalink to &quot;2. 对选择的焦虑&quot;">​</a></h3><p>纠结于选A还是选B，怕选错。</p><blockquote><p><strong>&quot;因上精进，果上随缘就是中观。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p><p>收集足够信息，做出当下最合理的决定，然后<strong>做就做了，不要回头纠结</strong>。</p><h3 id="_3-对评价的焦虑" tabindex="-1">3. 对评价的焦虑 <a class="header-anchor" href="#_3-对评价的焦虑" aria-label="Permalink to &quot;3. 对评价的焦虑&quot;">​</a></h3><p>怕被人看不起、怕做不好被人说。</p><blockquote><p><strong>&quot;若菩萨有我相、人相、众生相、寿者相，即非菩萨。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p><p>太在意别人的评价，是因为还有&quot;我相&quot;——我在别人心中是什么形象？放下这个&quot;我&quot;，就没有人需要评价我了。</p><hr><h2 id="三、实操方法" tabindex="-1">三、实操方法 <a class="header-anchor" href="#三、实操方法" aria-label="Permalink to &quot;三、实操方法&quot;">​</a></h2><p>了空居士给出的核心方法就一个：</p><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p><p>具体拆为三步：</p><ol><li><strong>觉察</strong>：问自己&quot;我现在在焦虑什么？&quot;把那个具体的事情说出来</li><li><strong>行动</strong>：&quot;做就是了。&quot;把焦虑拆成具体可执行的小步骤——担心考试→今天看哪一章</li><li><strong>放下</strong>：事情做了就放下。&quot;因上精进，果上随缘&quot;</li></ol><hr><h2 id="四、常见误解" tabindex="-1">四、常见误解 <a class="header-anchor" href="#四、常见误解" aria-label="Permalink to &quot;四、常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>焦虑就是软弱</td><td>焦虑是心对未来&quot;相&quot;的执着，人人都有</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr><tr><td>要完全消除焦虑才能修行</td><td>&quot;即得不等于得后&quot;——带着焦虑修，修着修着焦虑就淡了</td><td>—</td></tr><tr><td>想得多才能不焦虑</td><td>焦虑的反面是行动，不是过度分析</td><td>—</td></tr></tbody></table><hr><h2 id="五、推荐模型" tabindex="-1">五、推荐模型 <a class="header-anchor" href="#五、推荐模型" aria-label="Permalink to &quot;五、推荐模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — 不被未来的&quot;相&quot;带跑</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 将焦虑转化为行动</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 不执着绝对的好结果</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">对法不执</a> — 做了就放下</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-烦恼">dict-烦恼</a> — 焦虑是烦恼的一种</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-平常心">dict-平常心</a> — 平常心是对治焦虑的日常状态</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（全部原话添加原文段落链接，新增常见误解表，新增概念链接） 来源：金刚经第3分、第18分，答疑专辑</p></blockquote>',42)])])}const c=t(i,[["render",l]]);export{p as __pageData,c as default};
